const sliderDefs=[
 ['radius','Walking radius','R',5,65,1,'5 min','Unbounded','The catchment limit. Destinations beyond it do not contribute.','main'],
 ['beta','Distance sensitivity','β',0,.3,.005,'Gentle decay','Strong decay','Higher values place more emphasis on nearby destinations.','main'],
 ['shape','Decay shape','s',1,2,.05,'Exponential · 1','Gaussian · 2','Changes how quickly the distance penalty accelerates.','main'],
 ['exponent','Power-law exponent','α',.2,3,.1,'Long distance matters','Very local','Higher values concentrate the score around the nearest places.','main'],
 ['gamma','Competition strength','γ',0,1.5,.05,'None · 0','Stronger · 1.5','Discount facilities shared by more demand locations. γ = 1 gives full supply-to-demand weighting.','main'],
 ['speed','Walking speed','v',3,6.5,.1,'3 km/h','6.5 km/h','Converts the same road distances into walking minutes.','main'],
 ['a','Quantity emphasis','a',0,1,.05,'Average quality · 0','Total quantity · 1','At 1, more opportunities increase the total. At 0, read their weighted average.','advanced'],
 ['tau','Minimum-requirement emphasis','τ',0,1,.05,'Average cost · 0','Quota cost · 1','Blend average walking cost with the time needed to meet your quota. Available for walking-cost readout.','advanced'],
 ['rank','Required opportunity amount','r',.01,20,.01,'0.01 units','20 units','With equal weights, 1 means the nearest place and 3 means the third nearest. Weighted or competition-adjusted units differ.','advanced'],
 ['lower','Focus on harder-to-reach places','l',0,.9,.05,'All opportunities','Hardest 10%','Exclude the easiest share of opportunity mass before reading the remaining cost or benefit.','advanced'],
 ['p','Street sample emphasis','p',-5,5,1,'Smallest value','Largest value','Controls aggregation of street samples. Positive p emphasises larger values; for cost, these are worse positions.','advanced'],
 ['threshold','Minimum standard','t',.01,20,.01,'0.01 units','20 units','For coverage: each sample either meets this threshold or does not.','advanced']
];
for(const [key,label,symbol,min,max,step,low,high,help,group] of sliderDefs){const div=document.createElement('div');div.className='slider-field';div.id='field-'+key;div.innerHTML=`<div class="slider-head"><label for="param-${key}"><span class="slider-symbol">${symbol}</span>${label}</label><output id="value-${key}" for="param-${key}"></output></div><input id="param-${key}" type="range" min="${min}" max="${max}" step="${step}" aria-describedby="help-${key}"><div class="slider-ends"><span>${low}</span><span>${high}</span></div><p class="helper" id="help-${key}">${help}</p>`;$(group+'-sliders').append(div);$('param-'+key).oninput=e=>{state[key]=Number(e.target.value);sync();schedule();};}
function active(key){if(state.domain==='network')return key==='p'&&state.networkMetric!=='betweenness'||key==='speed'&&state.networkMetric!=='betweenness';if(key==='beta'||key==='shape')return ['exponential','gaussian'].includes(state.kernel);if(key==='exponent')return state.kernel==='power';if(key==='tau')return state.kernel==='identity';if(key==='rank')return state.tau>0;if(key==='threshold')return state.b===0;if(key==='radius')return !['identity','constant'].includes(state.kernel);if(key==='lower')return state.tau<1;return true;}
function number(v){if(!Number.isFinite(v))return '—';if(v===0)return '0';if(Math.abs(v)<.01)return v.toExponential(2);return v.toLocaleString('en-US',{maximumFractionDigits:Math.abs(v)<1?3:Math.abs(v)<100?2:0});}
function labelValue(k,v){return k==='radius'&&v>=65?'∞':k==='radius'?v+' min':k==='speed'?v.toFixed(1)+' km/h':k==='lower'?Math.round(v*100)+'%':k==='p'&&Math.abs(v)===5?(v>0?'Max':'Min'):number(v);}
function sync(){const matched=matchPreset(state),network=state.domain==='network';$('metric-name').textContent=matched?matched.name:'Custom accessibility';$('match-label').textContent=matched?'CLASSIC CONFIGURATION · '+matched.id:'YOUR PARAMETER COMBINATION';$('metric-description').textContent=matched?matched.description:customDescription();
 for(const [key]of sliderDefs){const el=$('param-'+key),enabled=active(key);el.value=state[key];el.disabled=!enabled;$('field-'+key).classList.toggle('inactive',!enabled);$('field-'+key).hidden=['shape','exponent','threshold','rank'].includes(key)&&!enabled;$('value-'+key).textContent=labelValue(key,state[key]);el.style.setProperty('--fill',(state[key]-Number(el.min))/(Number(el.max)-Number(el.min))*100+'%');}
 $('kernel').value=state.kernel;$('kernel').disabled=network;$('supply').value=state.supply;$('supply').disabled=network;$('response').value=state.b;$('response').disabled=network;$('response').querySelector('option[value="0"]').textContent=state.kernel==='identity'?'Exceeds a cost threshold':'Meets a minimum standard';$('help-threshold').textContent=state.kernel==='identity'?'Count samples whose cost is at least this threshold. A smaller share is better.':'Count samples whose opportunity value meets this minimum. A larger share is better.';
 $('supply-help').textContent=network?'Network indicators use junctions as destinations. Choose a POI category to return to facility access.':state.supply==='one'?'One mapped facility = one opportunity.':'Declared type weights: 1–4 units per facility. These are scenario assumptions, not measured capacity.';
 document.querySelectorAll('.category').forEach(b=>{b.classList.toggle('active',!network&&b.dataset.category===state.category);b.setAttribute('aria-pressed',String(!network&&b.dataset.category===state.category));});
 const cat=meta.categories.find(c=>c.id===state.category);$('poi-count').textContent=network?'Junction targets':cat.count.toLocaleString()+' places';$('map-title').textContent=network?'The structure of the streets.':({health:'Healthcare, within reach.',education:'A way to learn.',shopping:'Everyday essentials, closer.',recreation:'Room to play. Space to breathe.',civic:'Connected to community.'}[state.category]);$('network-count').textContent=meta.streets.toLocaleString()+' streets';$('model-tag').textContent='Walking · '+state.speed.toFixed(1)+' km/h';document.querySelectorAll('.preset-card').forEach(el=>el.classList.toggle('active',el.dataset.preset===matched?.id));}
function customDescription(){return `A custom ${state.kernel==='identity'?'walking cost':'opportunity value'} measure. ${state.gamma>0?'Competition is included. ':''}${state.lower>0?'Focuses on harder-to-reach opportunities. ':''}${state.a<1?'Balances quantity with average quality. ':''}${state.p!==1?'Changes how street samples are combined.':''}`;}
function updatePois(){poiLayer.clearLayers();if(!poiVisible||state.domain==='network'||map.getZoom()<14)return;for(const p of allPois)if(p.category===state.category)L.circleMarker([p.lat,p.lon],{renderer:poiRenderer,radius:3.5,color:'#197b80',weight:1.4,fillColor:'#fff',fillOpacity:.95}).bindTooltip(`<strong>${esc(p.name)}</strong><br>${esc(p.kind.replaceAll('_',' '))} · ${p.weight} scenario units<br>${number(p.connector)} m connector`).addTo(poiLayer);}
map.on('zoomend',updatePois);
const worker=new Worker('worker.js',{type:'module'});const pendingResolvers=new Map(),surfaceCache=new Map();
function completeWaiters(id){lastApplied=id;for(const [waiting,resolve]of pendingResolvers)resolve({completed:waiting===id,state:{...state},median:$('median-value').textContent,indicator:matchPreset(state)?.name??'Custom accessibility'});pendingResolvers.clear();}
function schedule(immediate=false){clearTimeout(timer);$('status').classList.remove('ready');$('status').textContent='Updating your perspective…';const id=++jobId;timer=setTimeout(async()=>{const copy={...state},preset=PRESETS.find(p=>Object.keys(p.params).every(k=>k==='category'||p.params[k]===copy[k]));if(preset){try{const key=copy.domain==='network'?'network':copy.category;if(!surfaceCache.has(key))surfaceCache.set(key,fetch('data/'+key+'-presets.json').then(r=>r.json()));const cache=await surfaceCache.get(key);if(id!==jobId)return;applyValues(Float64Array.from(cache[preset.id],v=>v===null?NaN:v));completeWaiters(id);return;}catch{surfaceCache.delete(copy.domain==='network'?'network':copy.category);}}if(id===jobId)worker.postMessage({id,state:copy});},immediate?0:180);return id;}
worker.onmessage=({data:d})=>{if(d.id!==jobId)return;if(d.type==='progress')$('status').textContent=d.text;if(d.type==='error'){applyValues(new Float64Array(net.streets.length).fill(NaN));$('status').classList.remove('ready');$('status').textContent='Calculation could not finish: '+d.text;for(const resolve of pendingResolvers.values())resolve({error:d.text});pendingResolvers.clear();}if(d.type==='result'){applyValues(d.values,d.elapsed,d.excluded);lastApplied=d.id;for(const [id,resolve]of pendingResolvers)resolve({completed:id===d.id,state:{...state},median:$('median-value').textContent,indicator:matchPreset(state)?.name??'Custom accessibility'});pendingResolvers.clear();}};
worker.onerror=e=>{applyValues(new Float64Array(net.streets.length).fill(NaN));$('status').classList.remove('ready');$('status').textContent='Calculation worker error: '+e.message;};
let color=createColorScale(PALETTES[0].colors),displayRange={lo:0,hi:1};
function recolor(stops){color=createColorScale(stops);if(!values)return;const {lo,hi}=displayRange;for(let i=0;i<values.length;i++){const v=values[i];lines[i].setStyle({color:Number.isFinite(v)?color(hi>lo?(v-lo)/(hi-lo):.5):'#b8c5c9'});}}
function applyValues(next,elapsed=0,excluded=0){values=next;const finite=Array.from(values).filter(Number.isFinite).sort((a,b)=>a-b),meaning=interpretation(state),q=p=>finite[Math.floor((finite.length-1)*p)],lo=q(.05),hi=q(.95),median=q(.5);displayRange={lo,hi};
 for(let i=0;i<values.length;i++){const v=values[i];let t=hi>lo?(v-lo)/(hi-lo):.5;lines[i].setStyle({color:Number.isFinite(v)?color(t):'#b8c5c9',weight:selected===i?6:2.8,opacity:selected===i?1:.93});}
 $('median-value').textContent=number(median);$('median-unit').textContent=meaning.unit;$('legend-title').textContent=state.b===0?(state.kernel==='identity'?'Cost exceedance':'Coverage'):'Street '+(meaning.unit==='minutes'?'walking time':'accessibility');$('legend-direction').textContent='Low → High';$('legend-direction').title=meaning.lower?'Lower values mean better access for this cost indicator.':'Higher values mean better access for this indicator.';$('legend-labels').innerHTML=[lo,(lo+hi)/2,hi].map(x=>`<span>${number(x)}</span>`).join('');
 $('status').classList.add('ready');$('status').textContent=`${finite.length.toLocaleString()} / ${values.length.toLocaleString()} valid street scores${elapsed?' · '+(elapsed/1000).toFixed(2)+' s':''}\n${state.gamma>0?'Demand scenario: one unit per junction':'OSM street network'}${excluded?' · '+excluded.toLocaleString()+' facilities excluded (zero model demand)':''}`;$('map').dataset.resultCount=values.length;$('map').dataset.median=median;$('map').dataset.checksum=Array.from(values).reduce((s,v,i)=>s+(Number.isFinite(v)?v*((i%97)+1):0),0).toFixed(6);if(selected>=0)renderSelection();}
function selectStreet(i){if(selected>=0)lines[selected].setStyle({weight:2.8,opacity:.93});selected=i;lines[i].setStyle({weight:6,opacity:1}).bringToFront();renderSelection();}
function renderSelection(){const s=net.streets[selected],value=values?.[selected];$('selection').hidden=false;$('selection').innerHTML=`<button class="close-selection" aria-label="Close selected street">×</button><div class="eyebrow">STREET ${s.id}</div><h3>${esc(s.name)}</h3><strong>${number(value)}</strong><p>${!Number.isFinite(value)?'Unreachable quota or undefined value':esc(interpretation(state).unit)} · ${number(s.m)} m long</p><p>${state.domain==='network'?(state.networkMetric==='betweenness'?'Raw all-pair edge betweenness.':'Junction scores mapped to the two street endpoints.'):(s.m>200?'Endpoints + midpoint, equal sample weights.':'Two endpoints, equal sample weights.')}<br><a target="_blank" rel="noreferrer" href="https://www.openstreetmap.org/way/${s.osm}">View source street ↗</a></p>`;$('selection').querySelector('button').onclick=()=>{lines[selected].setStyle({weight:2.8,opacity:.93});selected=-1;$('selection').hidden=true;};}
function choosePreset(id){const found=PRESETS.find(p=>p.id===id);if(!found)throw Error('Unknown indicator');state={...found.params,category:state.category};sync();updatePois();$('library').close();return schedule(true);}
for(const p of PRESETS){const b=document.createElement('button');b.className='preset-card';b.dataset.preset=p.id;b.innerHTML=`<span class="eyebrow">${p.id} / ${esc(p.family)}</span><strong>${esc(p.name)}</strong><p>${esc(p.description)}</p><code>${esc(p.formula)}</code>`;b.onclick=()=>choosePreset(p.id);$('preset-grid').append(b);}
$('kernel').onchange=e=>{state.kernel=e.target.value;state.tau=0;state.lower=0;state.b=1;if(state.kernel==='identity'){state.a=0;state.radius=65;}else state.a=1;if(state.kernel==='gaussian'){state.shape=2;state.beta=.01;}if(state.kernel==='exponential'){state.shape=1;state.beta=.08;}if(['step','linear','bands'].includes(state.kernel)&&state.radius>=65)state.radius=state.kernel==='bands'?30:15;sync();schedule();};$('supply').onchange=e=>{state.supply=e.target.value;sync();schedule();};$('response').onchange=e=>{state.b=Number(e.target.value);sync();schedule();};$('reset').onclick=()=>choosePreset('G1');
